__attribute__((unused)) static void
bpf_fault_bpf__assert(struct bpf_fault_bpf *s __attribute__((unused)))
{
#ifdef __cplusplus
#define _Static_assert static_assert
#endif
	_Static_assert(sizeof(s->rodata->backend_size) == 8, "unexpected size of 'backend_size'");
	_Static_assert(sizeof(s->bss->donated_size) == 8, "unexpected size of 'donated_size'");
	_Static_assert(sizeof(s->bss->revoked_size) == 8, "unexpected size of 'revoked_size'");
	_Static_assert(sizeof(s->bss->faulted_size) == 8, "unexpected size of 'faulted_size'");
#ifdef __cplusplus
#undef _Static_assert
#endif
}

